"""
高速フーリエ変換 (FFT / Fast Fourier Transform) & 多項式畳み込み
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
複素数を用いたCooley-Tukey型FFTにより、一般の実数・整数多項式の畳み込み (A(x) * B(x)) を O(N log N) で計算。
※ 厳密な mod 998244353 の計算は ntt.py を推奨。

【引数・戻り値】
- convolve_fft(a, b): 2つの数列 a, b の畳み込み積（整数丸め）を返す。
"""

import cmath

# https://github.com/ddfkit/acsampl/blob/main/fft.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def fft(a,inv=False):
    n=len(a)
    j=0
    for i in range(1,n):
        b=n>>1
        while j&b:j^=b;b>>=1
        j^=b
        if i<j:a[i],a[j]=a[j],a[i]
    l=2
    while l<=n:
        ang=2*cmath.pi/l*(-1 if inv else 1)
        w0=cmath.rect(1.0,ang);hl=l>>1
        for i in range(0,n,l):
            w=1.0
            for k in range(i,i+hl):
                u,v=a[k],a[k+hl]*w
                a[k],a[k+hl]=u+v,u-v;w*=w0
        l<<=1
    if inv:
        for i in range(n):a[i]/=n

# https://github.com/ddfkit/acsampl/blob/main/fft.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def convolve_fft(a,b):
    deg=len(a)+len(b)-1;n=1<<(deg-1).bit_length()
    fa=[complex(x,0) for x in a]+[0]*(n-len(a))
    fb=[complex(x,0) for x in b]+[0]*(n-len(b))
    fft(fa);fft(fb)
    for i in range(n):fa[i]*=fb[i]
    fft(fa,True)
    return [round(fa[i].real) for i in range(deg)]

if __name__ == "__main__":
    A = [1, 2, 3]
    B = [4, 5]
    C = convolve_fft(A, B)
    assert C == [4, 13, 22, 15]
    print("fft.py: tests passed!")
